package com.example.hiringsys.service; import com.example.hiringsys.entity.Rede; import com.example.hiringsys.exception.*; import com.example.hiringsys.repository.RedeRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.List;
@Service public class RedeService { private final RedeRepository repository; public RedeService(RedeRepository r){repository=r;} @Transactional(readOnly=true) public List<Rede> listarTodos(){return repository.findAll();} @Transactional(readOnly=true) public Rede buscarPorId(Long id){return repository.findById(id).orElseThrow(()->new ResourceNotFoundException("Rede não encontrada: "+id));} @Transactional public Rede salvar(Rede r){r.setId(null);validar(r.getUrl(),null);return repository.save(r);} @Transactional public Rede atualizar(Long id,Rede d){Rede r=buscarPorId(id);validar(d.getUrl(),id);r.setUrl(d.getUrl());r.setTipo(d.getTipo());return repository.save(r);} @Transactional public void excluir(Long id){repository.delete(buscarPorId(id));} private void validar(String u,Long id){boolean x=id==null?repository.existsByUrlIgnoreCase(u):repository.existsByUrlIgnoreCaseAndIdNot(u,id);if(x)throw new BusinessRuleException("URL já cadastrada: "+u);} }
